// Model forge: builds the five volcano components as Wavefront OBJ files.
//
//   dart run tool/forge_models.dart
//
// Every component is written to assets/models/ as plain OBJ with per-vertex
// colours (`v x y z r g b`), so each one opens directly in Blender and can be
// re-exported over the generated file.
//
// Conventions shared with the renderer (lib/engine):
//   * Y is up, the ground surface is y = 0, the base radius is 1 unit.
//   * Azimuth runs from +X toward +Z. The cutaway removes the quadrant
//     x > 0, z > 0, so every ring has a vertex on the planes x = 0 and z = 0.
//   * Material names (`usemtl`) tell the renderer how a face behaves.
import 'dart:io';
import 'dart:math';

const int kSegments = 48; // around the axis; a multiple of 4
const double kBaseRadius = 1.0;
const double kConeRadius = 0.92;
const double kRimRadius = 0.13;
const double kPeak = 0.78;
const double kCraterFloorY = 0.68;
const double kCraterFloorRadius = 0.07;
const double kBlockDepth = 0.56;
const double kLavaAzimuth = 135 * pi / 180;

/// Inset that keeps section faces just inside the quadrant that owns them.
const double _kInset = 0.0006;

class V3 {
  const V3(this.x, this.y, this.z);
  final double x, y, z;
  V3 operator +(V3 o) => V3(x + o.x, y + o.y, z + o.z);
  V3 operator -(V3 o) => V3(x - o.x, y - o.y, z - o.z);
  V3 operator *(double s) => V3(x * s, y * s, z * s);
  double dot(V3 o) => x * o.x + y * o.y + z * o.z;
  V3 cross(V3 o) => V3(y * o.z - z * o.y, z * o.x - x * o.z, x * o.y - y * o.x);
  double get length => sqrt(dot(this));
  V3 get normalized {
    final l = length;
    return l < 1e-12 ? const V3(0, 1, 0) : this * (1 / l);
  }
}

class Rgb {
  const Rgb(this.r, this.g, this.b);
  factory Rgb.hex(int hex) => Rgb(
    ((hex >> 16) & 0xff) / 255,
    ((hex >> 8) & 0xff) / 255,
    (hex & 0xff) / 255,
  );
  final double r, g, b;
  Rgb scale(double s) => Rgb(
    (r * s).clamp(0.0, 1.0),
    (g * s).clamp(0.0, 1.0),
    (b * s).clamp(0.0, 1.0),
  );
  static Rgb lerp(Rgb a, Rgb b, double t) =>
      Rgb(a.r + (b.r - a.r) * t, a.g + (b.g - a.g) * t, a.b + (b.b - a.b) * t);
}

/// Samples a list of (position, colour) stops.
Rgb ramp(List<(double, Rgb)> stops, double t) {
  if (t <= stops.first.$1) return stops.first.$2;
  for (var i = 1; i < stops.length; i++) {
    if (t <= stops[i].$1) {
      final a = stops[i - 1], b = stops[i];
      return Rgb.lerp(a.$2, b.$2, (t - a.$1) / (b.$1 - a.$1));
    }
  }
  return stops.last.$2;
}

/// Deterministic hash noise in [-1, 1].
double hash(int a, int b) {
  var h = (a * 374761393 + b * 668265263) & 0x7fffffff;
  h = ((h ^ (h >> 13)) * 1274126177) & 0x7fffffff;
  return ((h ^ (h >> 16)) & 0xffff) / 32767.5 - 1.0;
}

class _Face {
  _Face(this.a, this.b, this.c, this.material);
  final int a, b, c;
  final String material;
}

class ObjBuilder {
  ObjBuilder(this.name, this.title, {required this.smooth});

  final String name;
  final String title;

  /// Smooth meshes share one normal per vertex; flat meshes one per face.
  final bool smooth;

  final List<V3> _positions = [];
  final List<Rgb> _colors = [];
  final List<_Face> _faces = [];

  int vertex(V3 p, Rgb c) {
    if (!(p.x.isFinite && p.y.isFinite && p.z.isFinite)) {
      throw StateError('$name: non-finite vertex');
    }
    _positions.add(p);
    _colors.add(c);
    return _positions.length - 1;
  }

  /// Adds a triangle wound so that its normal agrees with [outward].
  void tri(int a, int b, int c, String material, V3 outward) {
    final n = (_positions[b] - _positions[a]).cross(
      _positions[c] - _positions[a],
    );
    if (n.length < 1e-10) return; // degenerate
    if (n.dot(outward) < 0) {
      _faces.add(_Face(a, c, b, material));
    } else {
      _faces.add(_Face(a, b, c, material));
    }
  }

  void quad(int a, int b, int c, int d, String material, V3 outward) {
    tri(a, b, c, material, outward);
    tri(a, c, d, material, outward);
  }

  int get triangleCount => _faces.length;

  String build() {
    final out = StringBuffer()
      ..writeln('# Vulcanic - $title')
      ..writeln('# Generated by tool/forge_models.dart')
      ..writeln('# ${_positions.length} vertices, ${_faces.length} triangles')
      ..writeln('mtllib volcano.mtl')
      ..writeln('o $name');
    String f(double v) {
      final s = v.toStringAsFixed(4);
      return s == '-0.0000' ? '0.0000' : s;
    }

    for (var i = 0; i < _positions.length; i++) {
      final p = _positions[i], c = _colors[i];
      out.writeln(
        'v ${f(p.x)} ${f(p.y)} ${f(p.z)} '
        '${c.r.toStringAsFixed(3)} ${c.g.toStringAsFixed(3)} '
        '${c.b.toStringAsFixed(3)}',
      );
    }

    V3 faceNormal(_Face t) => (_positions[t.b] - _positions[t.a]).cross(
      _positions[t.c] - _positions[t.a],
    );

    if (smooth) {
      final sums = List<V3>.filled(_positions.length, const V3(0, 0, 0));
      for (final t in _faces) {
        final n = faceNormal(t); // area weighted
        sums[t.a] += n;
        sums[t.b] += n;
        sums[t.c] += n;
      }
      for (final n in sums) {
        final u = n.normalized;
        out.writeln('vn ${f(u.x)} ${f(u.y)} ${f(u.z)}');
      }
    } else {
      for (final t in _faces) {
        final u = faceNormal(t).normalized;
        out.writeln('vn ${f(u.x)} ${f(u.y)} ${f(u.z)}');
      }
    }

    String? material;
    for (var i = 0; i < _faces.length; i++) {
      final t = _faces[i];
      if (t.material != material) {
        material = t.material;
        out.writeln('usemtl $material');
      }
      if (smooth) {
        out.writeln(
          'f ${t.a + 1}//${t.a + 1} ${t.b + 1}//${t.b + 1} '
          '${t.c + 1}//${t.c + 1}',
        );
      } else {
        out.writeln(
          'f ${t.a + 1}//${i + 1} ${t.b + 1}//${i + 1} '
          '${t.c + 1}//${i + 1}',
        );
      }
    }
    return out.toString();
  }
}

// ---------------------------------------------------------------------------
// Shared surface description
// ---------------------------------------------------------------------------

double _theta(int j) => 2 * pi * j / kSegments;

/// Point on the cone's outer slope. [u] runs 0 (base) to 1 (crater rim).
V3 coneSurface(double u, double theta) {
  u = u.clamp(0.0, 1.0);
  final r0 = kConeRadius - (kConeRadius - kRimRadius) * u;
  // Radial gullies, strongest mid-slope.
  final gullies =
      0.6 * sin(5 * theta + 0.7) +
      0.4 * sin(11 * theta + 2.1) +
      0.3 * sin(17 * theta + 4.0);
  final mid = sin(pi * u);
  final r = r0 * (1 + 0.05 * gullies * mid);
  var y = kPeak * pow(u, 1.75).toDouble();
  y += 0.018 * sin(7 * theta + 9 * u) * mid;
  // Uneven rim, breached on the side the lava spills from.
  final rim = pow(u, 6).toDouble();
  var d = (theta - kLavaAzimuth).abs();
  if (d > pi) d = 2 * pi - d;
  y += rim * (0.022 * sin(3 * theta + 1.0) - 0.05 * exp(-pow(d / 0.38, 2)));
  return V3(r * cos(theta), y, r * sin(theta));
}

/// Snaps azimuths that sit on a quadrant boundary exactly onto the plane.
V3 _snap(V3 p, int j, int segments) {
  final quarter = segments ~/ 4;
  if (j % quarter != 0) return p;
  final k = (j ~/ quarter) % 4;
  return k.isEven ? V3(p.x, p.y, 0) : V3(0, p.y, p.z);
}

const int _coneRings = 14;
double _ringU(int i) => pow(i / _coneRings, 0.85).toDouble();

/// Horizontal rock strata, top to bottom: (bottom y, colour).
final List<(double, Rgb)> _strata = [
  (-0.05, Rgb.hex(0x6b4f3a)), // soil
  (-0.19, Rgb.hex(0x86705b)), // tuff
  (-0.34, Rgb.hex(0x5c4d45)), // basalt
  (-0.45, Rgb.hex(0x77634f)), // sandstone
  (-kBlockDepth, Rgb.hex(0x3f3836)), // bedrock
];

/// Gentle waviness shared by the block wall and its section faces.
double _strataWave(double x, double z, int band) =>
    0.014 * sin(2.3 * x + 1.7 * z + band * 1.3);

// ---------------------------------------------------------------------------
// 01 - Volcanic cone
// ---------------------------------------------------------------------------

ObjBuilder forgeCone() {
  final b = ObjBuilder(
    'cone',
    'component 01: volcanic cone and crater',
    smooth: false,
  );
  final slope = <(double, Rgb)>[
    (0.00, Rgb.hex(0x55733b)),
    (0.20, Rgb.hex(0x6f6f3f)),
    (0.45, Rgb.hex(0x82603f)),
    (0.70, Rgb.hex(0x64504a)),
    (0.88, Rgb.hex(0x453a3b)),
    (1.00, Rgb.hex(0x2f2428)),
  ];

  // Outer slope: rings from the base up to the rim.
  final rings = <List<int>>[];
  for (var i = 0; i <= _coneRings; i++) {
    final u = _ringU(i);
    final ring = <int>[];
    for (var j = 0; j < kSegments; j++) {
      final p = _snap(coneSurface(u, _theta(j)), j, kSegments);
      final shade = 1 + 0.07 * hash(i, j);
      ring.add(
        b.vertex(i == 0 ? V3(p.x, 0, p.z) : p, ramp(slope, u).scale(shade)),
      );
    }
    rings.add(ring);
  }
  for (var i = 0; i < _coneRings; i++) {
    for (var j = 0; j < kSegments; j++) {
      final j2 = (j + 1) % kSegments;
      final mid = _theta(j) + pi / kSegments;
      b.quad(
        rings[i][j],
        rings[i][j2],
        rings[i + 1][j2],
        rings[i + 1][j],
        'cone_rock',
        V3(cos(mid), 0.6, sin(mid)),
      );
    }
  }

  // Crater: inner wall down to a flat floor.
  final wallColor = Rgb.hex(0x2c2120);
  final floorColor = Rgb.hex(0x1e1615);
  final rimInner = <int>[], floorRing = <int>[];
  for (var j = 0; j < kSegments; j++) {
    final t = _theta(j);
    final rim = _snap(coneSurface(1, t), j, kSegments);
    rimInner.add(b.vertex(rim, wallColor.scale(1 + 0.08 * hash(91, j))));
    floorRing.add(
      b.vertex(
        _snap(
          V3(
            kCraterFloorRadius * cos(t),
            kCraterFloorY,
            kCraterFloorRadius * sin(t),
          ),
          j,
          kSegments,
        ),
        floorColor,
      ),
    );
  }
  final center = b.vertex(const V3(0, kCraterFloorY, 0), floorColor);
  for (var j = 0; j < kSegments; j++) {
    final j2 = (j + 1) % kSegments;
    final mid = _theta(j) + pi / kSegments;
    b.quad(
      rimInner[j],
      rimInner[j2],
      floorRing[j2],
      floorRing[j],
      'cone_crater',
      V3(-cos(mid), 0.5, -sin(mid)),
    );
    b.tri(
      floorRing[j],
      floorRing[j2],
      center,
      'cone_crater',
      const V3(0, 1, 0),
    );
  }

  // Section faces shown by the cutaway: conformal ash and lava layers.
  final layers = <(double, Rgb)>[
    (0.22, Rgb.hex(0x4c403b)),
    (0.42, Rgb.hex(0x806c5a)),
    (0.60, Rgb.hex(0x55463f)),
    (0.76, Rgb.hex(0x917b66)),
    (0.90, Rgb.hex(0x5f4e45)),
    (1.00, Rgb.hex(0x3a3130)),
  ];
  void section({required bool alongX}) {
    // Profile from the axis outward: (radius, surface height).
    final theta = alongX ? 0.0 : pi / 2;
    final profile = <(double, double)>[
      (0, kCraterFloorY),
      (kCraterFloorRadius, kCraterFloorY),
    ];
    for (var i = _coneRings; i >= 0; i--) {
      final p = coneSurface(_ringU(i), theta);
      final r = alongX ? p.x : p.z;
      profile.add((r, i == 0 ? 0.0 : p.y));
    }
    V3 at(double r, double y) =>
        alongX ? V3(r, y, -_kInset) : V3(-_kInset, y, r);
    final outward = alongX ? const V3(0, 0, 1) : const V3(1, 0, 0);
    for (var i = 0; i < profile.length - 1; i++) {
      final (r0, y0) = profile[i];
      final (r1, y1) = profile[i + 1];
      var from = 0.0;
      for (final (to, color) in layers) {
        final a = b.vertex(at(r0, y0 * from), color);
        final c = b.vertex(at(r1, y1 * from), color);
        final d = b.vertex(at(r1, y1 * to), color.scale(1.06));
        final e = b.vertex(at(r0, y0 * to), color.scale(1.06));
        b.quad(a, c, d, e, 'cone_section', outward);
        from = to;
      }
    }
  }

  section(alongX: true);
  section(alongX: false);
  return b;
}

// ---------------------------------------------------------------------------
// 02 - Ground and underground rock block
// ---------------------------------------------------------------------------

ObjBuilder forgeTerrain() {
  final b = ObjBuilder(
    'terrain',
    'component 02: ground and rock layers',
    smooth: false,
  );
  final grass = Rgb.hex(0x5c7a3c);

  // Apron of ground between the foot of the cone and the edge of the block.
  final inner = <int>[], outer = <int>[];
  for (var j = 0; j < kSegments; j++) {
    final t = _theta(j);
    final foot = _snap(coneSurface(0, t), j, kSegments);
    inner.add(
      b.vertex(V3(foot.x, 0, foot.z), grass.scale(1 + 0.06 * hash(3, j))),
    );
    outer.add(
      b.vertex(
        _snap(V3(kBaseRadius * cos(t), 0, kBaseRadius * sin(t)), j, kSegments),
        grass.scale(0.94 + 0.06 * hash(4, j)),
      ),
    );
  }
  for (var j = 0; j < kSegments; j++) {
    final j2 = (j + 1) % kSegments;
    b.quad(
      inner[j],
      inner[j2],
      outer[j2],
      outer[j],
      'terrain_rock',
      const V3(0, 1, 0),
    );
  }

  // Cylindrical wall, one crisp band per stratum.
  var top = 0.0;
  for (var band = 0; band < _strata.length; band++) {
    final (bottom, color) = _strata[band];
    final last = band == _strata.length - 1;
    final upper = <int>[], lower = <int>[];
    for (var j = 0; j < kSegments; j++) {
      final t = _theta(j);
      final x = kBaseRadius * cos(t), z = kBaseRadius * sin(t);
      final yTop = band == 0 ? 0.0 : top + _strataWave(x, z, band - 1);
      final yBottom = last ? bottom : bottom + _strataWave(x, z, band);
      final shade = 1 + 0.05 * hash(20 + band, j);
      upper.add(
        b.vertex(
          _snap(V3(x, yTop, z), j, kSegments),
          color.scale(shade * 1.04),
        ),
      );
      lower.add(
        b.vertex(
          _snap(V3(x, yBottom, z), j, kSegments),
          color.scale(shade * 0.94),
        ),
      );
    }
    for (var j = 0; j < kSegments; j++) {
      final j2 = (j + 1) % kSegments;
      final mid = _theta(j) + pi / kSegments;
      b.quad(
        lower[j],
        lower[j2],
        upper[j2],
        upper[j],
        'terrain_rock',
        V3(cos(mid), 0, sin(mid)),
      );
    }
    top = bottom;
  }

  // Underside.
  final under = Rgb.hex(0x2c2726);
  final bottomRing = <int>[];
  for (var j = 0; j < kSegments; j++) {
    final t = _theta(j);
    bottomRing.add(
      b.vertex(
        _snap(
          V3(kBaseRadius * cos(t), -kBlockDepth, kBaseRadius * sin(t)),
          j,
          kSegments,
        ),
        under,
      ),
    );
  }
  final bottomCenter = b.vertex(const V3(0, -kBlockDepth, 0), under);
  for (var j = 0; j < kSegments; j++) {
    b.tri(
      bottomRing[j],
      bottomRing[(j + 1) % kSegments],
      bottomCenter,
      'terrain_rock',
      const V3(0, -1, 0),
    );
  }

  // Section faces: the same strata seen in cross-section.
  void section({required bool alongX}) {
    const columns = 10;
    V3 at(double r, double y) =>
        alongX ? V3(r, y, -_kInset) : V3(-_kInset, y, r);
    double wave(double r, int band) =>
        alongX ? _strataWave(r, 0, band) : _strataWave(0, r, band);
    final outward = alongX ? const V3(0, 0, 1) : const V3(1, 0, 0);
    var top = 0.0;
    for (var band = 0; band < _strata.length; band++) {
      final (bottom, color) = _strata[band];
      final last = band == _strata.length - 1;
      final fresh = color.scale(1.12);
      for (var c = 0; c < columns; c++) {
        final r0 = kBaseRadius * c / columns;
        final r1 = kBaseRadius * (c + 1) / columns;
        double yTop(double r) => band == 0 ? 0.0 : top + wave(r, band - 1);
        double yBottom(double r) => last ? bottom : bottom + wave(r, band);
        final a = b.vertex(at(r0, yBottom(r0)), fresh.scale(0.93));
        final d = b.vertex(at(r1, yBottom(r1)), fresh.scale(0.93));
        final e = b.vertex(at(r1, yTop(r1)), fresh);
        final g = b.vertex(at(r0, yTop(r0)), fresh);
        b.quad(a, d, e, g, 'terrain_section', outward);
      }
      top = bottom;
    }
  }

  section(alongX: true);
  section(alongX: false);
  return b;
}

// ---------------------------------------------------------------------------
// 03 - Magma chamber
// ---------------------------------------------------------------------------

const V3 kChamberCenter = V3(0, -0.34, 0);
const double kChamberRadius = 0.46;
const double kChamberHeight = 0.155;

ObjBuilder forgeChamber() {
  final b = ObjBuilder('chamber', 'component 03: magma chamber', smooth: true);
  const segments = 24, stacks = 10;
  final colors = <(double, Rgb)>[
    (0.0, Rgb.hex(0xb52f1b)),
    (0.5, Rgb.hex(0xf26a1b)),
    (1.0, Rgb.hex(0xffc04d)),
  ];
  final rings = <List<int>>[];
  for (var i = 1; i < stacks; i++) {
    final phi = pi * i / stacks; // 0 at the top pole
    final ring = <int>[];
    for (var j = 0; j < segments; j++) {
      final t = 2 * pi * j / segments;
      final lobes = 1 + 0.07 * sin(3 * t + 0.6) * sin(phi);
      final r = kChamberRadius * sin(phi) * lobes;
      final y = kChamberCenter.y + kChamberHeight * cos(phi);
      ring.add(
        b.vertex(
          _snap(V3(r * cos(t), y, r * sin(t)), j, segments),
          ramp(colors, (cos(phi) + 1) / 2),
        ),
      );
    }
    rings.add(ring);
  }
  final topPole = b.vertex(
    V3(0, kChamberCenter.y + kChamberHeight, 0),
    ramp(colors, 1),
  );
  final bottomPole = b.vertex(
    V3(0, kChamberCenter.y - kChamberHeight, 0),
    ramp(colors, 0),
  );
  for (var j = 0; j < segments; j++) {
    final j2 = (j + 1) % segments;
    final mid = 2 * pi * (j + 0.5) / segments;
    final out = V3(cos(mid), 0, sin(mid));
    b.tri(
      topPole,
      rings.first[j],
      rings.first[j2],
      'magma',
      out + const V3(0, 3, 0),
    );
    b.tri(
      bottomPole,
      rings.last[j],
      rings.last[j2],
      'magma',
      out + const V3(0, -3, 0),
    );
    for (var i = 0; i < rings.length - 1; i++) {
      b.quad(
        rings[i][j],
        rings[i][j2],
        rings[i + 1][j2],
        rings[i + 1][j],
        'magma',
        out,
      );
    }
  }
  return b;
}

// ---------------------------------------------------------------------------
// 04 - Main conduit
// ---------------------------------------------------------------------------

ObjBuilder forgeConduit() {
  final b = ObjBuilder('conduit', 'component 04: main conduit', smooth: true);
  const segments = 12, rings = 14;
  const yBottom = -0.24;
  final colors = <(double, Rgb)>[
    (0.0, Rgb.hex(0xffb347)),
    (0.6, Rgb.hex(0xff7a1f)),
    (1.0, Rgb.hex(0xff9a2e)),
  ];
  final loops = <List<int>>[];
  for (var i = 0; i <= rings; i++) {
    final v = i / rings;
    final y = yBottom + (kCraterFloorY - yBottom) * v;
    // Wide throat where it leaves the chamber, slight flare under the crater.
    final radius = 0.046 + 0.085 * exp(-v * 9) + 0.020 * pow(v, 8).toDouble();
    final loop = <int>[];
    for (var j = 0; j < segments; j++) {
      final t = 2 * pi * j / segments;
      loop.add(
        b.vertex(
          _snap(V3(radius * cos(t), y, radius * sin(t)), j, segments),
          ramp(colors, v),
        ),
      );
    }
    loops.add(loop);
  }
  for (var i = 0; i < rings; i++) {
    for (var j = 0; j < segments; j++) {
      final j2 = (j + 1) % segments;
      final mid = 2 * pi * (j + 0.5) / segments;
      b.quad(
        loops[i][j],
        loops[i][j2],
        loops[i + 1][j2],
        loops[i + 1][j],
        'conduit',
        V3(cos(mid), 0, sin(mid)),
      );
    }
  }
  return b;
}

// ---------------------------------------------------------------------------
// 05 - Surface lava flow
// ---------------------------------------------------------------------------

ObjBuilder forgeLava() {
  final b = ObjBuilder('lava', 'component 05: surface lava flow', smooth: true);
  const along = 34, across = 6; // across is even: a centre line of vertices
  final core = Rgb.hex(0xffcf5a);
  final body = Rgb.hex(0xff7a1f);
  final edge = Rgb.hex(0xb3200f);
  const groundReach = 0.985;

  final rows = <List<int>>[];
  for (var i = 0; i <= along; i++) {
    final s = i / along; // 0 at the crater, 1 at the toe
    // The first 82% runs down the slope, the rest spreads over the ground.
    final onSlope = s < 0.82;
    final u = onSlope ? 1 - s / 0.82 : 0.0;
    final ground = onSlope ? 0.0 : min(1.0, (s - 0.82) / 0.18);
    final centre =
        kLavaAzimuth + (9 * pi / 180) * sin(2.2 * pi * s) * min(1.0, s * 2);
    // Half-width as arc length; the toe swells and then rounds off.
    var half = 0.026 + 0.062 * s + 0.05 * ground;
    if (ground > 0.55) half *= sqrt(1 - pow((ground - 0.55) / 0.45, 2)) + 0.05;
    final thickness = 0.016 + 0.014 * s;
    final row = <int>[];
    for (var k = 0; k <= across; k++) {
      final w = k / across * 2 - 1; // -1 .. 1 across the flow
      V3 p;
      if (onSlope) {
        final foot = coneSurface(u, centre);
        final radius = sqrt(foot.x * foot.x + foot.z * foot.z);
        p = coneSurface(u, centre + w * half / radius);
      } else {
        final foot = coneSurface(0, centre);
        final footRadius = sqrt(foot.x * foot.x + foot.z * foot.z);
        final radius = footRadius + (groundReach - footRadius) * ground;
        final t = centre + w * half / radius;
        p = V3(radius * cos(t), 0, radius * sin(t));
      }
      final lift = 0.006 + thickness * (1 - w * w);
      final heat = 1 - w.abs();
      final color = heat > 0.5
          ? Rgb.lerp(body, core, (heat - 0.5) * 2)
          : Rgb.lerp(edge, body, heat * 2);
      row.add(b.vertex(V3(p.x, p.y + lift, p.z), color));
    }
    rows.add(row);
  }
  for (var i = 0; i < along; i++) {
    for (var k = 0; k < across; k++) {
      b.quad(
        rows[i][k],
        rows[i][k + 1],
        rows[i + 1][k + 1],
        rows[i + 1][k],
        'lava',
        const V3(-0.4, 1, 0.4),
      );
    }
  }
  return b;
}

