/// Material library so the components open with sensible colours in Blender.
const String kMaterialLibrary = '''
# Vulcanic - shared materials. Vertex colours carry the detail.
newmtl cone_rock
Kd 0.38 0.34 0.28
newmtl cone_crater
Kd 0.15 0.11 0.10
newmtl cone_section
Kd 0.42 0.35 0.30
newmtl terrain_rock
Kd 0.40 0.34 0.28
newmtl terrain_section
Kd 0.46 0.39 0.32
newmtl magma
Kd 0.95 0.42 0.11
Ke 0.80 0.30 0.05
newmtl conduit
Kd 1.00 0.48 0.12
Ke 0.80 0.30 0.05
newmtl lava
Kd 1.00 0.48 0.12
Ke 0.90 0.35 0.05
''';

/// Every generated file, keyed by file name.
Map<String, String> forgeAll() => {
  'cone.obj': forgeCone().build(),
  'terrain.obj': forgeTerrain().build(),
  'chamber.obj': forgeChamber().build(),
  'conduit.obj': forgeConduit().build(),
  'lava.obj': forgeLava().build(),
  'volcano.mtl': kMaterialLibrary.trimLeft(),
};

void main() {
  final dir = Directory('assets/models')..createSync(recursive: true);
  forgeAll().forEach((name, text) {
    File('${dir.path}/$name').writeAsStringSync(text);
    final faces = RegExp(r'^f ', multiLine: true).allMatches(text).length;
    stdout.writeln(
      '${name.padRight(12)} ${faces.toString().padLeft(5)} '
      'triangles  ${(text.length / 1024).toStringAsFixed(1)} KB',
    );
  });
}
